-- PRODUCTION baseline for schema_migrations — prepared 2026-10-23, NOT executed.
--
-- Source: `scripts/migrate.py detect` + `baseline` run against the production
-- database (Proxmox VM 101) with default_transaction_read_only=on.
--   * 27 files: every table/index/column/view/function they create exists.
--   * 003_backfill_users_telegram_id.sql (data-only, not auto-detectable):
--     included by hand — 0 users have telegram_chat_id without telegram_id.
--   * NOT included (objects absent in production, never applied there):
--       004_create_data_quality_tables.sql
--       005_create_data_quality_fix_log.sql
--       006_dissertation_merge_support.sql
--     Only the data_quality module and its scripts need them; apply them with
--     `scripts/migrate.py apply --yes` only as part of a reviewed release.
--
-- Run (after review, from the deployed checkout so checksums match):
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f deploy/schema_migrations_baseline_production_2026-10-23.sql
--   python scripts/migrate.py status      # expect exactly the 3 files above pending
--
-- Checksums are sha256 of the migration files on integrate/main-2026-10;
-- `status` reports CHANGED if the deployed files differ.
-- schema_migrations baseline: records files whose objects already exist.
-- Generated by scripts/migrate.py baseline. Review before running.
BEGIN;
CREATE TABLE IF NOT EXISTS schema_migrations (
    filename    TEXT PRIMARY KEY,
    checksum    CHAR(64) NOT NULL,
    applied_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    applied_by  TEXT,
    method      VARCHAR(20) NOT NULL DEFAULT 'applied'
                CHECK (method IN ('applied', 'baseline'))
);
